async function seed() {
  for (const trek of treks) {
    try {
      await client.patch(trek.id).set(trek.data).commit();
      console.log(`Seeded: ${trek.data.title}`);
    } catch (err) {
      console.error(`Failed: ${trek.data.title}`, err.message);
    }
  }
  console.log('\nAll remaining region treks seeded!');
}

